actions.script:
invoiceMap = {}
const cf = ec.entity.conditionFactory
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    const all = !!vis.allProjects
    let scope = all ? null : Array.from(vis.visibleProjectIds || [])
    if (rootWorkEffortId) { if (scope && !scope.includes(rootWorkEffortId)) return; scope = [rootWorkEffortId] }
    if (scope && !scope.length) return
    const ids = invoiceIds != null ? Array.from(invoiceIds).map(String).filter((id) => id) : null
    if (ids != null && !ids.length) return
    const add = (invoiceId, projectId, kind) => {
        if (!invoiceId || !projectId) return
        if (scope && !scope.includes(projectId)) return
        const entry = invoiceMap[invoiceId] || (invoiceMap[invoiceId] = {kind: kind, projectIds: []})
        if (kind === 'worker' || (kind === 'client' && entry.kind === 'expense')) entry.kind = kind
        if (!entry.projectIds.includes(projectId)) entry.projectIds.push(projectId)
    }
    const rootOf = (row) => row.workEffortTypeEnumId === 'WetProject' ? row.workEffortId : (row.rootWorkEffortId || null)
    const scoped = (field) => {
        const conds = [cf.makeCondition(field, 'is-not-null', null)]
        if (ids) conds.push(cf.makeCondition(field, 'in', ids))
        if (scope) conds.push(cf.makeCondition([cf.makeCondition('rootWorkEffortId', 'in', scope), cf.makeCondition('workEffortId', 'in', scope)], 'or'))
        return cf.makeCondition(conds, 'and')
    }
    // the time billed: client invoices by invoiceId, worker invoices by vendorInvoiceId
    for (const [field, kind] of [['invoiceId', 'client'], ['vendorInvoiceId', 'worker']]) {
        const seen = new Set()
        for (const row of ec.entity.find('mantle.work.time.TimeEntryAndWorkEffort').condition(scoped(field)).selectField(field).selectField('workEffortId')
                .selectField('rootWorkEffortId').selectField('workEffortTypeEnumId').limit(50000).list()) {
            const key = row[field] + ' ' + rootOf(row)
            if (seen.has(key)) continue
            seen.add(key)
            add(row[field], rootOf(row), kind)
        }
    }
    // the invoices linked to a project or its items
    let links = ec.entity.find('mantle.work.effort.WorkEffortInvoice')
    if (ids) links = links.condition('invoiceId', 'in', ids)
    const linkRows = Array.from(links.limit(20000).list())
    const efforts = {}
    const effortIds = Array.from(new Set(linkRows.map((row) => row.workEffortId)))
    for (let i = 0; i < effortIds.length; i += 1000) for (const row of ec.entity.find('mantle.work.effort.WorkEffort')
            .condition('workEffortId', 'in', effortIds.slice(i, i + 1000)).selectField('workEffortId').selectField('rootWorkEffortId')
            .selectField('workEffortTypeEnumId').list()) efforts[row.workEffortId] = row
    const clients = {}
    const clientOf = (projectId) => {
        if (!(projectId in clients)) clients[projectId] = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', projectId)
                .condition('roleTypeId', 'in', ['Customer', 'CustomerBillTo']).list()).map((row) => row.partyId)
        return clients[projectId]
    }
    const linkInvoiceIds = Array.from(new Set(linkRows.map((row) => row.invoiceId)))
    const toParty = {}
    for (let i = 0; i < linkInvoiceIds.length; i += 1000) for (const row of ec.entity.find('mantle.account.invoice.Invoice')
            .condition('invoiceId', 'in', linkInvoiceIds.slice(i, i + 1000)).selectField('invoiceId').selectField('toPartyId').list()) toParty[row.invoiceId] = row.toPartyId
    for (const link of linkRows) {
        const effort = efforts[link.workEffortId]
        if (!effort) continue
        const projectId = rootOf(effort)
        if (!projectId) continue
        add(link.invoiceId, projectId, clientOf(projectId).includes(toParty[link.invoiceId]) ? 'client' : 'expense')
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

canView = false; invoice = null; kind = null; projectIds = []
const money = ec.service.sync().name('ironstone.BillingServices.check#Money').parameters({need: 'none'}).call()?.managesMoney
if (money) {
    const row = ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', invoiceId).disableAuthz().one()
    const found = row ? (ec.service.sync().name('ironstone.BillingServices.get#InvoiceProjects').parameters({invoiceIds: [invoiceId]}).call()?.invoiceMap || {})[invoiceId] : null
    if (row && found) { canView = true; invoice = row.getMap(); kind = found.kind; projectIds = found.projectIds }
}
if (!canView && need !== 'none') ec.message.addError(ec.resource.expand('Invoice ${invoiceId} is not available', '', {invoiceId}))

draft = null
ec.service.sync().name('ironstone.BillingServices.check#Money').call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'manage'}).call()
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const out = ec.service.sync().name('mantle.work.ProjectServices.get#UnbilledSummary').parameters({workEffortId: workEffortId, withEntries: true}).call() || {}
if (ec.message.hasError()) return
const row = Array.from(out.projectList || [])[0]
const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).disableAuthz().one()
const settingsOut = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: workEffortId}).call() || {}
const settings = settingsOut.settings || {}
const defaults = ec.service.sync().name('ironstone.BillingServices.get#BillingSettings').parameters({organizationPartyId: settingsOut.organizationPartyId || null}).call()?.defaults || {}
const groupings = {PerEntry: 'entry', PerWorker: 'worker', OneLine: 'all'}
const uom = row?.currencyUomId || 'USD'
const money = (value) => value == null ? '' : ec.l10n.formatCurrency(value, uom)
const hoursText = (value) => value == null ? '' : ec.l10n.format(value, '#,##0.##')
const entries = Array.from(row?.entryList || [])
const ready = entries.filter((entry) => entry.ready)
draft = {workEffortId: workEffortId, projectName: project?.workEffortName || workEffortId, clientPartyId: row?.clientPartyId || null, clientName: row?.clientName || '',
    canInvoice: !!row?.canInvoice, cannotReason: row ? (row.cannotReason || '') : L('Nothing to invoice'),
    entryGrouping: groupings[settings.WstInvoiceGrouping] || 'entry', settlementTermId: defaults.settlementTermId || '',
    readyHoursText: row ? hoursText(row.readyHours) : '0', readyAmountText: row ? money(row.readyAmount) : money(toDecimal(0)),
    waitingHoursText: row ? hoursText(toDecimal(row.waitingHours).add(row.openHours)) : '0', currencyUomId: uom,
    entryOptions: ready.map((entry) => ({key: entry.timeEntryId, missingRate: entry.missingRate,
        text: [ec.l10n.format(new Date(entry.fromDate), 'MMM d'), entry.personName, (entry.workEffortId === workEffortId ? '' : entry.workEffortId + ' ') + entry.workEffortName,
            hoursText(entry.hours) + ' h', entry.missingRate ? L('no rate') : money(entry.amount)].filter((part) => part).join(' · ')
            + (entry.comments ? ' — ' + entry.comments.substring(0, 60) : '')})),
    selectedIds: ready.filter((entry) => !entry.missingRate).map((entry) => entry.timeEntryId),
    draftOptions: Array.from(row?.draftInvoiceList || []).map((inv) => ({key: inv.invoiceId,
        text: inv.invoiceId + ' · ' + (inv.invoiceDate != null ? ec.l10n.format(new Date(inv.invoiceDate), 'MMM d, yyyy') + ' · ' : '') + money(inv.invoiceTotal)}))}

const L = (text) => ec.l10n.localize(text)
itemCount = 0
ec.service.sync().name('ironstone.BillingServices.check#Money').call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'manage'}).call()
if (ec.message.hasError()) return
if (!['entry', 'worker', 'all'].includes(entryGrouping)) { ec.message.addError(L('Group by entry, by worker or in one line')); return }
const out = ec.service.sync().name('mantle.work.ProjectServices.get#UnbilledSummary').parameters({workEffortId: workEffortId, withEntries: true}).call() || {}
if (ec.message.hasError()) return
const row = Array.from(out.projectList || [])[0]
if (!row) { ec.message.addError(L('The project has no billable time to invoice')); return }
if (!row.clientPartyId) { ec.message.addError(L('The project has no client')); return }
if (!row.vendorPartyId) { ec.message.addError(L('The project has no vendor to bill from')); return }
const ready = {}
for (const entry of Array.from(row.entryList || [])) if (entry.ready) ready[entry.timeEntryId] = entry
let selected = null
const given = timeEntryIds == null ? [] : (typeof timeEntryIds === 'string' ? timeEntryIds.split(',') : Array.from(timeEntryIds).map(String))
if (selection && !given.some((id) => id.trim())) { ec.message.addError(L('Select the time to invoice')); return }
if (given.some((id) => id.trim())) {
    selected = Array.from(new Set(given.map((id) => id.trim()).filter((id) => id)))
    const notReady = selected.filter((id) => !ready[id])
    if (notReady.length) { ec.message.addError(ec.resource.expand('Not approved time to invoice: ${ids}', '', {ids: notReady.join(', ')})); return }
}
const chosen = selected ? selected.map((id) => ready[id]) : Object.values(ready)
if (!chosen.length) { ec.message.addError(L('No approved time to invoice')); return }
const noRate = chosen.filter((entry) => entry.missingRate)
if (noRate.length) { ec.message.addError(ec.resource.expand('${count} entries have no client rate: set the rates first (${ids})', '', {count: noRate.length,
    ids: noRate.slice(0, 5).map((entry) => entry.timeEntryId).join(', ')})); return }
if (invoiceId) {
    const target = ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', invoiceId).disableAuthz().one()
    if (!target || !Array.from(row.draftInvoiceList || []).some((inv) => inv.invoiceId === invoiceId)) {
        ec.message.addError(ec.resource.expand('Invoice ${invoiceId} is not an open draft of this project to its client', '', {invoiceId})); return }
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const made = ec.service.sync().name('mantle.account.InvoiceServices.create#ProjectInvoiceItems').parameters({workEffortId: workEffortId, invoiceId: invoiceId || null,
        approvedOnly: true, billableOnly: true, timeEntryIdList: chosen.map((entry) => entry.timeEntryId), entryGrouping: entryGrouping,
        settlementTermId: settlementTermId || null, invoiceDate: invoiceDate || ec.user.nowTimestamp}).call() || {}
    if (ec.message.hasError()) return
    invoiceId = made.invoiceId
    itemCount = Number(made.invoiceItemCreatedCount || 0)
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
message = ec.resource.expand('Invoice ${invoiceId}: ${count} lines added', '', {invoiceId: invoiceId, count: itemCount})

rowList = []; counts = {}; projectOptions = []; clientOptions = []
const lists = ['drafts', 'toSend', 'sent', 'overdue', 'paid', 'worker', 'all']
if (!lists.includes(list)) list = 'all'
ec.service.sync().name('ironstone.BillingServices.check#Money').call()
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const map = ec.service.sync().name('ironstone.BillingServices.get#InvoiceProjects').parameters({rootWorkEffortId: rootWorkEffortId || null}).call()?.invoiceMap || {}
const ids = Object.keys(map)
if (!ids.length) { for (const key of lists) counts[key] = 0; return }
const invoices = []
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    for (let i = 0; i < ids.length; i += 1000) for (const row of ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', 'in', ids.slice(i, i + 1000)).list()) invoices.push(row)
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
const nowMillis = Number(String(ec.user.nowTimestamp))
const millis = (value) => value == null ? null : Number(String(value))
const unpaidOf = (inv) => toDecimal(inv.unpaidTotal ?? inv.invoiceTotal ?? 0)
const listOf = (inv, kind) => {
    const status = inv.statusId
    const keys = ['all']
    if (kind === 'worker') keys.push('worker')
    if (['InvoiceInProcess', 'InvoiceIncoming', 'InvoiceReceived'].includes(status)) keys.push('drafts')
    if (status === 'InvoiceFinalized') keys.push('toSend')
    if (['InvoiceSent', 'InvoiceAcked'].includes(status)) keys.push('sent')
    if (['InvoicePmtRecvd', 'InvoicePmtSent'].includes(status)) keys.push('paid')
    if (['InvoiceFinalized', 'InvoiceSent', 'InvoiceAcked', 'InvoiceApproved'].includes(status) && millis(inv.dueDate) != null
            && millis(inv.dueDate) < nowMillis && unpaidOf(inv).compare(0) > 0) keys.push('overdue')
    return keys
}
const names = {}
const nameOf = (id) => {
    if (!id) return ''
    if (!(id in names)) {
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).disableAuthz().one()
        names[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
    }
    return names[id]
}
const projectNames = {}
const projectName = (id) => {
    if (!(id in projectNames)) projectNames[id] = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).disableAuthz().one()?.workEffortName || id
    return projectNames[id]
}
const statusText = {}
const statusOf = (id) => {
    if (!id) return ''
    if (!(id in statusText)) statusText[id] = ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id
    return statusText[id]
}
const colors = {InvoiceInProcess: 'blue-grey-6', InvoiceIncoming: 'blue-grey-6', InvoiceReceived: 'blue-grey-6', InvoiceFinalized: 'primary', InvoiceApproved: 'primary',
    InvoiceSent: 'info', InvoiceAcked: 'info', InvoicePmtRecvd: 'positive', InvoicePmtSent: 'positive', InvoiceCancelled: 'grey-6', InvoiceWriteOff: 'warning'}
const kindLabels = {client: 'Client', worker: 'Worker', expense: 'Expense'}
for (const key of lists) counts[key] = 0
const from = fromDate != null ? millis(fromDate) : null
const thru = thruDate != null ? millis(thruDate) : null
const clients = {}, projects = {}
for (const inv of invoices) {
    const entry = map[inv.invoiceId]
    const keys = listOf(inv, entry.kind)
    if (entry.kind === 'client') clients[inv.toPartyId] = nameOf(inv.toPartyId)
    for (const id of entry.projectIds) projects[id] = projectName(id)
    // the find narrows the chips' counts as it does the list
    if (clientPartyId && inv.toPartyId !== clientPartyId) continue
    if (kind && entry.kind !== kind) continue
    const invoiceMillis = millis(inv.invoiceDate)
    if (from != null && (invoiceMillis == null || invoiceMillis < from)) continue
    if (thru != null && (invoiceMillis == null || invoiceMillis >= thru)) continue
    for (const key of keys) counts[key]++
    if (!keys.includes(list)) continue
    const uom = inv.currencyUomId || 'USD'
    const overdue = keys.includes('overdue')
    rowList.push({invoiceId: inv.invoiceId, url: '/qapps/Projects/Billing/InvoiceDetail?invoiceId=' + encodeURIComponent(inv.invoiceId), kind: entry.kind,
        kindText: L(kindLabels[entry.kind]), projectText: entry.projectIds.map(projectName).join(', '), projectIds: entry.projectIds,
        fromName: nameOf(inv.fromPartyId), toName: nameOf(inv.toPartyId), invoiceDate: invoiceMillis,
        dateText: invoiceMillis == null ? '' : ec.l10n.format(new Date(invoiceMillis), 'MMM d, yyyy'),
        dueText: inv.dueDate == null ? '' : ec.l10n.format(inv.dueDate, 'MMM d, yyyy'), overdue: overdue,
        totalText: ec.l10n.formatCurrency(toDecimal(inv.invoiceTotal ?? 0), uom), unpaidText: ['InvoiceCancelled'].includes(inv.statusId) ? '' : ec.l10n.formatCurrency(unpaidOf(inv), uom),
        statusId: inv.statusId, statusLabel: overdue ? statusOf(inv.statusId) + ' · ' + L('Overdue') : statusOf(inv.statusId),
        statusColor: overdue ? 'negative' : (colors[inv.statusId] || 'grey-8'), description: inv.description || ''})
}
rowList.sort((a, b) => (b.invoiceDate ?? 0) - (a.invoiceDate ?? 0) || String(b.invoiceId).localeCompare(String(a.invoiceId)))
clientOptions = Object.keys(clients).filter((id) => id).map((id) => ({key: id, text: clients[id]})).sort((a, b) => a.text.localeCompare(b.text))
projectOptions = Object.keys(projects).map((id) => ({key: id, text: projects[id]})).sort((a, b) => a.text.localeCompare(b.text))

detail = null
const access = ec.service.sync().name('ironstone.BillingServices.get#InvoiceAccess').parameters({invoiceId: invoiceId, need: 'none'}).call() || {}
if (!access.canView) return
const L = (text) => ec.l10n.localize(text)
const inv = access.invoice
const uom = inv.currencyUomId || 'USD'
const money = (value) => value == null ? '' : ec.l10n.formatCurrency(value, uom)
const hoursText = (value) => value == null ? '' : ec.l10n.format(value, '#,##0.##')
const day = (value) => value == null ? '' : ec.l10n.format(value instanceof Date ? value : new Date(Number(String(value))), 'MMM d, yyyy')
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const nameOf = (id) => {
        if (!id) return ''
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
        return party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
    }
    const statusOf = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
    const enumOf = (id) => id ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id) : ''
    const time = ec.service.sync().name('mantle.account.InvoiceServices.get#InvoiceTimeDetail').parameters({invoiceId: invoiceId}).call() || {}
    const entries = Array.from(time.entryList || [])
    const items = Array.from(ec.entity.find('mantle.account.invoice.InvoiceItem').condition('invoiceId', invoiceId).orderBy('invoiceItemSeqId').list())
    const totalOf = (item) => toDecimal(item.quantity ?? 1).multiply(toDecimal(item.amount ?? 0)).setScale(2, 'HALF_UP')
    const status = inv.statusId
    const isClient = access.kind === 'client'
    const isDraft = status === 'InvoiceInProcess'
    const itemRows = items.map((item) => {
        const itemEntries = entries.filter((entry) => (entry.invoiceItemSeqId || '') === item.invoiceItemSeqId)
        const hours = itemEntries.reduce((total, entry) => total.add(entry.hours), toDecimal(0))
        return {invoiceItemSeqId: item.invoiceItemSeqId, typeText: enumOf(item.itemTypeEnumId), description: item.description || '',
            itemDateText: item.itemDate != null ? day(item.itemDate) : '', quantityText: item.quantity == null ? '1' : ec.l10n.format(item.quantity, '#,##0.##'),
            amountText: money(toDecimal(item.amount ?? 0)), totalText: money(totalOf(item)), entryCount: itemEntries.length,
            timeText: itemEntries.length ? ec.resource.expand('${count} entries, ${hours} h', '', {count: itemEntries.length, hours: hoursText(hours)}) : '',
            canRemove: isClient && isDraft}
    })
    const entryRows = entries.map((entry) => ({timeEntryId: entry.timeEntryId, invoiceItemSeqId: entry.invoiceItemSeqId || '', personName: entry.personName,
        dayText: entry.fromDate == null ? '' : ec.l10n.format(new Date(entry.fromDate), 'EEE MMM d'),
        itemText: entry.workEffortId ? (entry.workEffortId === entry.rootWorkEffortId ? entry.workEffortName : entry.workEffortId + ' ' + entry.workEffortName) : '',
        itemUrl: entry.workEffortId && entry.workEffortId !== entry.rootWorkEffortId ? '/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=' + encodeURIComponent(entry.workEffortId) : null,
        hoursText: hoursText(entry.hours), rateText: entry.rate == null ? '' : money(entry.rate), amountText: entry.amount == null ? '' : money(entry.amount),
        comments: entry.comments || ''}))
    const payments = Array.from(ec.entity.find('mantle.account.payment.PaymentApplication').condition('invoiceId', invoiceId).list()).map((pa) => ({
        paymentId: pa.paymentId || pa.toInvoiceId || '', amountText: money(toDecimal(pa.amountApplied ?? 0)), dateText: pa.appliedDate != null ? day(pa.appliedDate) : ''}))
    const projects = Array.from(access.projectIds || []).map((id) => ({workEffortId: id, name: ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one()?.workEffortName || id,
        url: '/qapps/Projects/Projects/ProjectDetail?workEffortId=' + encodeURIComponent(id)}))
    // the address to send to: the client's billing email, its billing contact's on the project, else its primary
    let sendTo = ''
    if (isClient && inv.toPartyId) {
        const billing = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', inv.toPartyId)
                .condition('contactMechPurposeId', 'EmailBilling').conditionDate('fromDate', 'thruDate', null).list())[0]
        sendTo = billing?.infoString || ''
        if (!sendTo && projects.length) {
            const contact = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', projects[0].workEffortId)
                    .condition('roleTypeId', 'ClientBilling').conditionDate('fromDate', 'thruDate', null).list())[0]
            if (contact) sendTo = ec.service.sync().name('mantle.party.ContactServices.get#PrimaryEmailAddress').parameters({partyId: contact.partyId}).call()?.emailAddress || ''
        }
        if (!sendTo) sendTo = ec.service.sync().name('mantle.party.ContactServices.get#PrimaryEmailAddress').parameters({partyId: inv.toPartyId}).call()?.emailAddress || ''
    }
    const total = toDecimal(inv.invoiceTotal ?? 0)
    const unpaid = toDecimal(inv.unpaidTotal ?? inv.invoiceTotal ?? 0)
    const overdue = ['InvoiceFinalized', 'InvoiceSent', 'InvoiceAcked'].includes(status) && inv.dueDate != null
            && Number(String(inv.dueDate)) < Number(String(ec.user.nowTimestamp)) && unpaid.compare(0) > 0
    const term = inv.settlementTermId ? ec.entity.find('mantle.account.invoice.SettlementTerm').condition('settlementTermId', inv.settlementTermId).useCache(true).one() : null
    const firstProject = projects[0]?.workEffortId
    const timeDetail = firstProject ? (ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: firstProject}).call()?.settings?.WstTimeDetail !== 'N') : true
    detail = {invoiceId: invoiceId, kind: access.kind, kindText: L({client: 'Client invoice', worker: 'Worker invoice', expense: 'Expense invoice'}[access.kind] || 'Invoice'),
        statusId: status, statusLabel: statusOf(status), isDraft: isDraft, isClient: isClient, overdue: overdue,
        fromPartyId: inv.fromPartyId, fromName: nameOf(inv.fromPartyId), toPartyId: inv.toPartyId, toName: nameOf(inv.toPartyId),
        invoiceDateText: day(inv.invoiceDate), invoiceDateValue: inv.invoiceDate == null ? '' : ec.l10n.format(inv.invoiceDate, 'yyyy-MM-dd'),
        dueDateText: day(inv.dueDate), termText: term ? (term.description || term.settlementTermId) : '', settlementTermId: inv.settlementTermId || '',
        referenceNumber: inv.referenceNumber || '', description: inv.description || '', invoiceMessage: inv.invoiceMessage || '',
        currencyUomId: uom, totalText: money(total), unpaidText: money(unpaid), paidText: money(total.subtract(unpaid)), hoursText: hoursText(time.hours ?? toDecimal(0)),
        timeAmountText: money(time.amount ?? toDecimal(0)), itemRows: itemRows, entryRows: entryRows, payments: payments, projects: projects,
        projectText: projects.map((project) => project.name).join(', '), sendTo: sendTo, timeDetail: timeDetail,
        printUrl: '/apps/Projects/Billing/InvoicePrint?renderMode=html-print&invoiceId=' + encodeURIComponent(invoiceId),
        pdfUrl: '/fop/apps/Projects/Billing/InvoicePrint?invoiceId=' + encodeURIComponent(invoiceId) + '&filename=Invoice-' + encodeURIComponent(invoiceId) + '.pdf',
        canApprove: isClient && isDraft && items.length > 0, canSend: isClient && ['InvoiceInProcess', 'InvoiceFinalized', 'InvoiceSent', 'InvoiceAcked'].includes(status) && items.length > 0,
        sendAgain: ['InvoiceSent', 'InvoiceAcked'].includes(status), canResume: isClient && status === 'InvoiceFinalized',
        canCancel: isClient && ['InvoiceInProcess', 'InvoiceFinalized'].includes(status), canEdit: isClient && isDraft,
