if (ec.message.hasError()) return
const org = ec.service.sync().name('ironstone.ProjectServices.get#SettingsOrganization').call()?.organizationPartyId
if (!org) { ec.message.addError(L('You belong to no organization, so there is nowhere to keep the setting')); return }
if (!['TimeAndMaterials', 'FixedPrice', 'Milestones', 'NotBilled'].includes(billingBasis)) { ec.message.addError(L('Choose the billing basis')); return }
if (!['PerEntry', 'PerWorker', 'OneLine'].includes(invoiceGrouping)) { ec.message.addError(L('Choose how invoice lines are grouped')); return }
if (!['Monthly', 'ByProject'].includes(workerInvoicing || 'Monthly')) { ec.message.addError(L('Choose how contractors bill their time')); return }
if (settlementTermId && !ec.entity.find('mantle.account.invoice.SettlementTerm').condition('settlementTermId', settlementTermId).useCache(true).one()) {
    ec.message.addError(L('Not a payment term')); return }
const value = JSON.stringify({billingBasis: billingBasis, invoiceGrouping: invoiceGrouping, timeDetail: timeDetail === 'Y', shareHours: shareHours === 'Y',
    settlementTermId: settlementTermId || undefined, workerInvoicing: workerInvoicing || 'Monthly'})
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    ec.service.sync().name('store#mantle.party.PartySetting').parameters({partyId: org, partySettingTypeId: 'ProjBillingDefaults', settingValue: value}).call()
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (!ec.message.hasError()) message = L('Billing defaults saved')
